package com.smartcampusguardian.service;

import com.smartcampusguardian.dto.IncidentRequest;
import com.smartcampusguardian.entity.*;
import com.smartcampusguardian.exception.*;
import com.smartcampusguardian.repository.UserRepository;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class CampusOperationsService {
 private final JdbcTemplate jdbc; private final UserRepository users; private final TriageService triage;
 public CampusOperationsService(JdbcTemplate jdbc, UserRepository users, TriageService triage) { this.jdbc=jdbc; this.users=users; this.triage=triage; }
 private Long userId(String username) { return users.findByEmailIgnoreCase(username).or(() -> users.findByRegisterNumber(username)).map(User::getId).orElseThrow(()->new ResourceNotFoundException("Authenticated user not found")); }
 private void audit(Long actor,String action,String entity,Long id,String detail) { jdbc.update("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,detail) VALUES (?,?,?,?,?)",actor,action,entity,id,detail); }
 private void timeline(Long incident,Long actor,String oldStatus,String newStatus,String message) { jdbc.update("INSERT INTO incident_updates(incident_id,updated_by,old_status,new_status,message) VALUES (?,?,?,?,?)",incident,actor,oldStatus,newStatus,message); }
 private void notifyRoles(String title,String message,String type) { jdbc.update("INSERT INTO notifications(user_id,title,message,notification_type) SELECT id,?,?,? FROM users WHERE role IN ('ROLE_ADMIN','ROLE_SECURITY') AND account_status='ACTIVE'",title,message,type); }
 public List<Map<String,Object>> zones() { return jdbc.queryForList("SELECT id,name,description,risk_level,latitude,longitude,active FROM campus_zones WHERE active=true ORDER BY name"); }
 @Transactional public Map<String,Object> createIncident(String username, IncidentRequest request) {
  Long reporter=userId(username); Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM campus_zones WHERE id=? AND active=true",Integer.class,request.zoneId()); if(exists==null||exists==0) throw new BusinessRuleException("Select an active campus zone");
  int sequence=jdbc.queryForObject("SELECT COUNT(*) FROM incidents",Integer.class)+1; String code; do { code="SCG-%d-%06d".formatted(Year.now().getValue(),sequence++); } while(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM incidents WHERE incident_code=?)",Boolean.class,code)));
  IncidentSeverity severity=triage.calculateSeverity(request.incidentType()); jdbc.update("INSERT INTO incidents(incident_code,reported_by,incident_type,description,zone_id,severity,status,is_silent,anonymous_report) VALUES(?,?,?,?,?,?, 'REPORTED',?,?)",code,reporter,request.incidentType().name(),request.description(),request.zoneId(),severity.name(),request.silent(),request.anonymousReport());
  Long id=jdbc.queryForObject("SELECT id FROM incidents WHERE incident_code=?",Long.class,code); timeline(id,reporter,null,"REPORTED","Incident created"); timeline(id,reporter,"REPORTED","REPORTED","Rule-based emergency triage calculated "+severity); notifyRoles(request.silent()?"Silent SOS activated":"New campus incident",code+" requires review.","INCIDENT"); audit(reporter,request.silent()?"SILENT_SOS_CREATED":"INCIDENT_CREATED","INCIDENT",id,code); return Map.of("id",id,"incidentCode",code,"severity",severity.name(),"status","REPORTED");
 }
 public List<Map<String,Object>> studentIncidents(String username) { return jdbc.queryForList("SELECT i.id,i.incident_code,i.incident_type,i.severity,i.status,i.is_silent,i.created_at,z.name zone FROM incidents i LEFT JOIN campus_zones z ON z.id=i.zone_id WHERE i.reported_by=? ORDER BY i.created_at DESC",userId(username)); }
 public Map<String,Object> incident(Long id,String username,boolean admin) { Long user=userId(username); String sql="SELECT i.id,i.incident_code,i.incident_type,i.description,i.severity,i.status,i.is_silent,i.anonymous_report,i.created_at,z.name zone,CASE WHEN i.anonymous_report THEN 'Anonymous Student' ELSE u.full_name END reporter FROM incidents i JOIN users u ON u.id=i.reported_by LEFT JOIN campus_zones z ON z.id=i.zone_id WHERE i.id=?"+(admin?"":" AND i.reported_by=?"); List<Map<String,Object>> rows=admin?jdbc.queryForList(sql,id):jdbc.queryForList(sql,id,user); if(rows.isEmpty()) throw new ResourceNotFoundException("Incident not found"); Map<String,Object> result=new LinkedHashMap<>(rows.getFirst()); result.put("timeline",jdbc.queryForList("SELECT iu.created_at,iu.old_status,iu.new_status,iu.message,COALESCE(u.full_name,'System') updated_by FROM incident_updates iu LEFT JOIN users u ON u.id=iu.updated_by WHERE iu.incident_id=? ORDER BY iu.created_at",id)); return result; }
 public List<Map<String,Object>> allIncidents() { return jdbc.queryForList("SELECT i.id,i.incident_code,i.incident_type,i.severity,i.status,i.created_at,z.name zone,CASE WHEN i.anonymous_report THEN 'Anonymous Student' ELSE u.full_name END reporter FROM incidents i JOIN users u ON u.id=i.reported_by LEFT JOIN campus_zones z ON z.id=i.zone_id ORDER BY i.created_at DESC"); }
 @Transactional public void assign(Long incidentId,Long officerId,String username) { Long admin=userId(username); Map<String,Object> incident=single("SELECT id,status FROM incidents WHERE id=?",incidentId,"Incident not found"); Integer officer=jdbc.queryForObject("SELECT COUNT(*) FROM security_officers WHERE id=?",Integer.class,officerId); if(officer==null||officer==0) throw new ResourceNotFoundException("Security officer not found"); jdbc.update("INSERT INTO incident_assignments(incident_id,officer_id) VALUES (?,?)",incidentId,officerId); jdbc.update("UPDATE incidents SET status='ASSIGNED',assigned_at=CURRENT_TIMESTAMP WHERE id=?",incidentId); timeline(incidentId,admin,(String)incident.get("status"),"ASSIGNED","Security officer assigned"); jdbc.update("INSERT INTO notifications(user_id,title,message,notification_type) SELECT user_id,?,?, 'ASSIGNMENT' FROM security_officers WHERE id=?","Incident assigned","You have been assigned incident "+incidentId,officerId); audit(admin,"OFFICER_ASSIGNED","INCIDENT",incidentId,"Officer "+officerId); }
 public List<Map<String,Object>> assignments(String username) { Long user=userId(username); return jdbc.queryForList("SELECT i.id,i.incident_code,i.incident_type,i.description,i.severity,i.status,i.created_at,z.name zone,ia.assigned_at,ia.accepted_at FROM incident_assignments ia JOIN security_officers so ON so.id=ia.officer_id JOIN incidents i ON i.id=ia.incident_id LEFT JOIN campus_zones z ON z.id=i.zone_id WHERE so.user_id=? ORDER BY ia.assigned_at DESC",user); }
 @Transactional public void transition(Long incidentId,String target,String notes,String username) { Long actor=userId(username); Map<String,Object> row=single("SELECT i.status FROM incidents i JOIN incident_assignments ia ON ia.incident_id=i.id JOIN security_officers so ON so.id=ia.officer_id WHERE i.id=? AND so.user_id=? ORDER BY ia.assigned_at DESC LIMIT 1",incidentId,actor,"Assigned incident not found"); String old=(String)row.get("status"); Map<String,String> allowed=Map.of("ASSIGNED","ACKNOWLEDGED","ACKNOWLEDGED","RESPONDING","RESPONDING","ARRIVED","ARRIVED","RESOLVED"); if(!target.equals(allowed.get(old))) throw new BusinessRuleException("Invalid incident transition from "+old+" to "+target); String stamp=switch(target){case "ACKNOWLEDGED"->"acknowledged_at";case "RESPONDING"->"responding_at";case "ARRIVED"->"arrived_at";default->"resolved_at";}; jdbc.update("UPDATE incidents SET status=?, "+stamp+"=CURRENT_TIMESTAMP, resolution_notes=CASE WHEN ?='RESOLVED' THEN ? ELSE resolution_notes END WHERE id=?",target,target,notes,incidentId); if(target.equals("ACKNOWLEDGED")) jdbc.update("UPDATE incident_assignments ia JOIN security_officers so ON so.id=ia.officer_id SET ia.accepted_at=CURRENT_TIMESTAMP WHERE ia.incident_id=? AND so.user_id=?",incidentId,actor); if(target.equals("RESOLVED")) jdbc.update("UPDATE incident_assignments ia JOIN security_officers so ON so.id=ia.officer_id SET ia.completed_at=CURRENT_TIMESTAMP WHERE ia.incident_id=? AND so.user_id=?",incidentId,actor); timeline(incidentId,actor,old,target,notes==null||notes.isBlank()?"Officer marked incident "+target:notes); jdbc.update("INSERT INTO notifications(user_id,title,message,notification_type) SELECT reported_by,?,?, 'STATUS' FROM incidents WHERE id=?","Incident status updated","Incident "+incidentId+" is now "+target,incidentId); audit(actor,"INCIDENT_"+target,"INCIDENT",incidentId,notes); }
 public Map<String,Object> dashboard(String username) { Long id=userId(username); return Map.of("openIncidents",jdbc.queryForObject("SELECT COUNT(*) FROM incidents WHERE reported_by=? AND status NOT IN ('RESOLVED','CANCELLED')",Integer.class,id),"alerts",jdbc.queryForObject("SELECT COUNT(*) FROM campus_alerts WHERE active=true AND (expires_at IS NULL OR expires_at>CURRENT_TIMESTAMP)",Integer.class),"notifications",jdbc.queryForObject("SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL",Integer.class,id),"recentIncidents",studentIncidents(username)); }
 public List<Map<String,Object>> alerts(){return jdbc.queryForList("SELECT id,title,message,severity,created_at,expires_at FROM campus_alerts WHERE active=true AND (expires_at IS NULL OR expires_at>CURRENT_TIMESTAMP) ORDER BY created_at DESC");}
 public List<Map<String,Object>> notifications(String username){return jdbc.queryForList("SELECT id,title,message,notification_type,read_at,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC",userId(username));}
 public List<Map<String,Object>> adminDashboard(){return jdbc.queryForList("SELECT (SELECT COUNT(*) FROM users WHERE role='ROLE_STUDENT') students,(SELECT COUNT(*) FROM incidents WHERE status NOT IN ('RESOLVED','CANCELLED')) active_incidents,(SELECT COUNT(*) FROM incidents WHERE DATE(created_at)=CURRENT_DATE) today_incidents,(SELECT COUNT(*) FROM security_officers WHERE availability_status='AVAILABLE') available_officers");}
 public List<Map<String,Object>> analytics(){return jdbc.queryForList("SELECT severity,COUNT(*) total FROM incidents GROUP BY severity UNION ALL SELECT status,COUNT(*) total FROM incidents GROUP BY status");}
 public List<Map<String,Object>> contacts(String username){return jdbc.queryForList("SELECT id,name,relationship_name,phone,is_primary FROM emergency_contacts WHERE user_id=? ORDER BY is_primary DESC,name",userId(username));}
 @Transactional public void addContact(String username,String name,String relationship,String phone,boolean primary){Long u=userId(username);if(primary)jdbc.update("UPDATE emergency_contacts SET is_primary=false WHERE user_id=?",u);jdbc.update("INSERT INTO emergency_contacts(user_id,name,relationship_name,phone,is_primary) VALUES(?,?,?,?,?)",u,name,relationship,phone,primary);audit(u,"EMERGENCY_CONTACT_ADDED","EMERGENCY_CONTACT",null,name);}
 public List<Map<String,Object>> safeWalks(String username){return jdbc.queryForList("SELECT sw.id,sw.status,sw.requested_at,sw.completed_at,s.name start_zone,d.name destination_zone FROM safe_walks sw LEFT JOIN campus_zones s ON s.id=sw.start_zone_id LEFT JOIN campus_zones d ON d.id=sw.destination_zone_id WHERE sw.student_id=? ORDER BY sw.requested_at DESC",userId(username));}
 @Transactional public void requestSafeWalk(String username,Long start,Long destination){Long u=userId(username);jdbc.update("INSERT INTO safe_walks(student_id,start_zone_id,destination_zone_id,status) VALUES(?,?,?,'REQUESTED')",u,start,destination);audit(u,"SAFE_WALK_REQUESTED","SAFE_WALK",null,"Requested escort");}
 @Transactional public void createAlert(String username,String title,String message,String severity){Long u=userId(username);jdbc.update("INSERT INTO campus_alerts(title,message,severity,active,created_by) VALUES(?,?,?,true,?)",title,message,severity,u);jdbc.update("INSERT INTO notifications(user_id,title,message,notification_type) SELECT id,?,?, 'ALERT' FROM users WHERE role='ROLE_STUDENT'",title,message);audit(u,"CAMPUS_ALERT_CREATED","CAMPUS_ALERT",null,title);}
 @Transactional public Long createCheckIn(String username,String title,String message){Long u=userId(username);jdbc.update("INSERT INTO safety_checkins(title,message,created_by,status) VALUES(?,?,?,'OPEN')",title,message,u);Long id=jdbc.queryForObject("SELECT MAX(id) FROM safety_checkins",Long.class);jdbc.update("INSERT INTO notifications(user_id,title,message,notification_type) SELECT id,?,?, 'CHECK_IN' FROM users WHERE role='ROLE_STUDENT'",title,message);audit(u,"SAFETY_CHECKIN_CREATED","SAFETY_CHECKIN",id,title);return id;}
 @Transactional public void respondCheckIn(String username,Long checkin,String response){Long u=userId(username);jdbc.update("INSERT INTO safety_checkin_responses(checkin_id,user_id,response_status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE response_status=VALUES(response_status),responded_at=CURRENT_TIMESTAMP",checkin,u,response);if("NEED_HELP".equals(response))notifyRoles("Safety check-in needs help","Student requested help in safety check-in "+checkin,"CHECK_IN");audit(u,"SAFETY_CHECKIN_RESPONSE","SAFETY_CHECKIN",checkin,response);}
 public List<Map<String,Object>> checkIns(){return jdbc.queryForList("SELECT c.id,c.title,c.message,c.status,c.created_at,SUM(r.response_status='SAFE') safe_count,SUM(r.response_status='NEED_HELP') need_help_count FROM safety_checkins c LEFT JOIN safety_checkin_responses r ON r.checkin_id=c.id GROUP BY c.id,c.title,c.message,c.status,c.created_at ORDER BY c.created_at DESC");}
 @Transactional public Long createDrill(String username,String title,String description){Long u=userId(username);jdbc.update("INSERT INTO drills(title,description,status,created_by) VALUES(?,?,'PLANNED',?)",title,description,u);Long id=jdbc.queryForObject("SELECT MAX(id) FROM drills",Long.class);audit(u,"DRILL_CREATED","DRILL",id,title);return id;}
 public List<Map<String,Object>> drills(){return jdbc.queryForList("SELECT d.id,d.title,d.description,d.status,d.scheduled_at,d.created_at,COUNT(r.id) responses FROM drills d LEFT JOIN drill_responses r ON r.drill_id=d.id GROUP BY d.id,d.title,d.description,d.status,d.scheduled_at,d.created_at ORDER BY d.created_at DESC");}
 public List<Map<String,Object>> clusters(){return jdbc.queryForList("SELECT z.name zone,i.incident_type,COUNT(*) related_incidents,MAX(i.created_at) latest_report FROM incidents i JOIN campus_zones z ON z.id=i.zone_id WHERE i.created_at >= DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 10 MINUTE) GROUP BY z.name,i.incident_type HAVING COUNT(*) >= 3");}
 public Map<String,Object> riskIndex(){Integer active=jdbc.queryForObject("SELECT COUNT(*) FROM incidents WHERE status NOT IN ('RESOLVED','CANCELLED')",Integer.class);Integer critical=jdbc.queryForObject("SELECT COUNT(*) FROM incidents WHERE severity='CRITICAL' AND status NOT IN ('RESOLVED','CANCELLED')",Integer.class);int score=Math.max(0,100-(active*8+critical*12));return Map.of("score",score,"level",score>=75?"LOW":score>=50?"MODERATE":score>=25?"HIGH":"CRITICAL","simulation",true);}
 public List<Map<String,Object>> audits(){return jdbc.queryForList("SELECT a.created_at,a.action,a.entity_type,a.entity_id,a.detail,COALESCE(u.full_name,'System') actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT 200");}
 private Map<String,Object> single(String sql,Object id,String message){List<Map<String,Object>> r=jdbc.queryForList(sql,id);if(r.isEmpty())throw new ResourceNotFoundException(message);return r.getFirst();}
 private Map<String,Object> single(String sql,Object id,Object user,String message){List<Map<String,Object>> r=jdbc.queryForList(sql,id,user);if(r.isEmpty())throw new ResourceNotFoundException(message);return r.getFirst();}
}
